import{_ as e,o as r,c as t,ae as l}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"匯率切換說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/05-exchange-rate-guide.md","filePath":"v1/zh-HK/guide/05-exchange-rate-guide.md"}'),i={name:"v1/zh-HK/guide/05-exchange-rate-guide.md"};function o(h,a,n,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="匯率切換說明" tabindex="-1">匯率切換說明 <a class="header-anchor" href="#匯率切換說明" aria-label="Permalink to &quot;匯率切換說明&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>考拉記帳支援多幣種記帳，並提供匯率查詢與切換。</p><hr><h2 id="💰-本位幣" tabindex="-1">💰 本位幣 <a class="header-anchor" href="#💰-本位幣" aria-label="Permalink to &quot;💰 本位幣&quot;">​</a></h2><p>本位幣是帳本的主要貨幣，用於統一顯示與統計計算。</p><p>主要用途：</p><ul><li>統一顯示金額</li><li>概覽/統計的計算口徑</li><li>匯率列表以本位幣為基準顯示</li></ul><h2 id="🚀-如何切換本位幣" tabindex="-1">🚀 如何切換本位幣 <a class="header-anchor" href="#🚀-如何切換本位幣" aria-label="Permalink to &quot;🚀 如何切換本位幣&quot;">​</a></h2><ul><li>設定 → 貨幣設定 → 本位幣</li><li>帳本管理 → 帳本詳情 → 帳本貨幣</li></ul><p>切換後系統會更新顯示與統計。</p><hr><h2 id="📊-匯率列表" tabindex="-1">📊 匯率列表 <a class="header-anchor" href="#📊-匯率列表" aria-label="Permalink to &quot;📊 匯率列表&quot;">​</a></h2><p>你可以：</p><ul><li>查看支援的貨幣與匯率</li><li>點擊右上角刷新按鈕獲取最新匯率</li></ul><blockquote><p>💡 提示：離線時可能會使用已保存的匯率資料。</p></blockquote><h2 id="💱-顯示規則" tabindex="-1">💱 顯示規則 <a class="header-anchor" href="#💱-顯示規則" aria-label="Permalink to &quot;💱 顯示規則&quot;">​</a></h2><p>系統會以 <strong>目前匯率</strong> 進行換算顯示；刷新匯率或切換本位幣後，歷史帳單的換算顯示可能會跟著變化。原始交易金額不會改變。</p><hr><h2 id="🔄-快取" tabindex="-1">🔄 快取 <a class="header-anchor" href="#🔄-快取" aria-label="Permalink to &quot;🔄 快取&quot;">​</a></h2><p>為了提升效能，匯率會在 App 內暫存。</p><ul><li>手動刷新、切換本位幣或帳本貨幣時會更新匯率資料</li></ul><hr><h2 id="⚙️-手動修改匯率" tabindex="-1">⚙️ 手動修改匯率 <a class="header-anchor" href="#⚙️-手動修改匯率" aria-label="Permalink to &quot;⚙️ 手動修改匯率&quot;">​</a></h2><p>在某些情況下，你可以在匯率設定頁手動輸入匯率值並保存，保存後會影響相關顯示與計算。</p><hr><h2 id="🔧-常見問題" tabindex="-1">🔧 常見問題 <a class="header-anchor" href="#🔧-常見問題" aria-label="Permalink to &quot;🔧 常見問題&quot;">​</a></h2><h3 id="q1-切換本位幣後-歷史帳單金額會變嗎" tabindex="-1">Q1：切換本位幣後，歷史帳單金額會變嗎？ <a class="header-anchor" href="#q1-切換本位幣後-歷史帳單金額會變嗎" aria-label="Permalink to &quot;Q1：切換本位幣後，歷史帳單金額會變嗎？&quot;">​</a></h3><p>換算後的<strong>顯示金額</strong>可能變化，但<strong>原始交易金額</strong>不會改變。</p><h3 id="q2-匯率看起來不準怎麼辦" tabindex="-1">Q2：匯率看起來不準怎麼辦？ <a class="header-anchor" href="#q2-匯率看起來不準怎麼辦" aria-label="Permalink to &quot;Q2：匯率看起來不準怎麼辦？&quot;">​</a></h3><p>請嘗試點擊刷新按鈕更新匯率，並確認網路連線正常。</p><hr><p><strong>最後更新</strong>：2026 年 5 月</p>',33)])])}const q=e(i,[["render",o]]);export{p as __pageData,q as default};
